using System.ComponentModel.DataAnnotations; using Movers.Services.Pickups;
namespace Movers.Api.Contracts.Pickups;
public sealed record SavePickupStatusRequest([Required] string Code,[Required] string Name,int DisplayOrder,string? Color,bool IsCompleted){public SavePickupStatusCommand Command()=>new(Code,Name,DisplayOrder,Color,IsCompleted);}
public sealed record SaveVehicleRequest([Required] string RegistrationNumber,[Required] string Name,[Required] string Type,[Range(.001,100000)] decimal CapacityCbm,string? DriverName,string? DriverPhone){public SaveVehicleCommand Command()=>new(RegistrationNumber,Name,Type,CapacityCbm,DriverName,DriverPhone);}
public sealed record SetPickupMasterStatusRequest(bool IsActive);
public sealed record SavePickupRequest(string? PickupNumber,Guid? QuotationId,[Required] string CustomerName,[Required] string Phone,string? Email,[Required] string Address,DateTimeOffset ScheduledAtUtc,Guid StatusId,Guid? VehicleId,string? Notes,Guid? SalesLeadId=null){public SavePickupCommand Command()=>new(PickupNumber ?? "",QuotationId,CustomerName,Phone,Email,Address,ScheduledAtUtc,StatusId,VehicleId,Notes,SalesLeadId);}
public sealed record AssignmentRequest(Guid EmployeeId,[Required] string Role); public sealed record PackageItemRequest([Required,StringLength(160)] string ItemName,[Range(1,10000)] int Quantity,[StringLength(500)] string? Notes,[StringLength(120)] string? RoomName=null,Guid? HouseholdItemId=null); public sealed record PackageRequest(Guid BoxTypeId,string? TrackingNumber,[StringLength(500)] string? Notes,IReadOnlyList<PackageItemRequest> Items,[StringLength(120)] string? RoomName=null,bool IsFragile=false); public sealed record MaterialRequest(Guid MaterialId,[Range(.001,100000)] decimal Quantity,decimal? UnitCost); public sealed record SavePickupDetailRequest(IReadOnlyList<AssignmentRequest> Assignments,IReadOnlyList<PackageRequest> Packages,IReadOnlyList<MaterialRequest> Materials){public SavePickupDetailCommand Command()=>new(Assignments.Select(x=>new AssignmentInput(x.EmployeeId,x.Role)).ToList(),Packages.Select(x=>new PackageInput(x.BoxTypeId,x.TrackingNumber,x.Notes,x.Items.Select(i=>new PackageItemInput(i.ItemName,i.Quantity,i.Notes,i.RoomName,i.HouseholdItemId)).ToList(),x.RoomName,x.IsFragile)).ToList(),Materials.Select(x=>new MaterialInput(x.MaterialId,x.Quantity,x.UnitCost)).ToList());}
public sealed record AddPickupTransactionRequest([Required] string Type,[Required] string Category,[Range(.01,999999999)] decimal Amount,[Required] string PaymentMethod,string? Notes,string? Currency=null,decimal? ExchangeRate=null){public AddTransactionCommand Command()=>new(Type,Category,Amount,PaymentMethod,Notes,Currency,ExchangeRate);} public sealed record PickupLinkRequest([Range(1,30)] int ValidDays=7); public sealed record ConfirmPickupRequest(DateTimeOffset ScheduledAtUtc,decimal? Latitude,decimal? Longitude,string? Address){public ConfirmPickupCommand Command()=>new(ScheduledAtUtc,Latitude,Longitude,Address);}

